	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	// Read n1, n2
	scanner.Scan()
	parts := strings.Fields(scanner.Text())
	n1, _ := strconv.ParseInt(parts[0], 10, 64)
	n2, _ := strconv.ParseInt(parts[1], 10, 64)

	// Read n
	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())

	idx := (n - 1) % 6
	neg := false
	current := n1

	if idx >= 3 {
		neg = true
		idx -= 3
	}

	switch idx {
	case 1:
		current = n2
	case 2:
		current = n2 - n1
	}

	if neg {
		current = -current
	}

	mod := int64(1000000007)
	result := (current%mod + mod) % mod
	fmt.Println(result)
}

